'use strict';
const KEY='aula-semilla-v1';
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const now=()=>new Date().toISOString();
const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('es-EC',{day:'numeric',month:'short',year:'numeric'}):'Sin fecha';
const byId=id=>LESSONS.find(l=>l.id===id);
const areaById=id=>AREAS.find(a=>a.id===id);
const shuffle=items=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
function newStudent(name){return{id:uid(),name,logs:[],tasks:[],quiz:null};}
function freshState(){const s=newStudent('Mi estudiante');return{version:1,active:s.id,students:[s]};}
let state,storageFailed=false;
try{const raw=localStorage.getItem(KEY);state=raw?sanitize(JSON.parse(raw)):freshState();}catch{state=freshState();storageFailed=true;}
let practiceMode=false;
let lessonTab=location.hash.slice(1).split('/')[2]||'aprender',gameType='match',game=null,search='',filterArea='all',toastTimer;
function current(){return state.students.find(s=>s.id===state.active)||state.students[0];}
function save(){if(Classroom.isStudent())return;if(Teacher.isCloud()){Teacher.schedule(JSON.stringify(state));return;}try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;toast('No se pudo guardar en este navegador. Exporta una copia desde Datos y fuentes.');}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
function log(lesson,type,score,extra={}){current().logs.push({id:uid(),lesson,type,score,date:now(),...extra});current().logs=current().logs.slice(-1000);Classroom.record(current().logs[current().logs.length-1]);save();}
function latest(id,type){return [...current().logs].reverse().find(x=>x.lesson===id&&x.type===type);}
function status(l){const decision=Classroom.mastery(l.id);if(decision)return decision.consolidated?{label:'Consolidado · docente',css:'',rank:3}:{label:'Reforzar · docente',css:'warn',rank:1};const k=latest(l.id,'knowledge'),e=latest(l.id,'evidence'),d=latest(l.id,'diag');if((Teacher.isAllowed()||Classroom.isStudent())&&k&&k.score>=75&&e&&e.levels.every(v=>v>=3))return{label:'Consolidado',css:'',rank:3};if(k||e||latest(l.id,'match')||latest(l.id,'puzzle'))return{label:'En práctica',css:'warn',rank:2};if(d)return{label:d.score<75?'Reforzar':'Verificar en clase',css:d.score<75?'warn':'gray',rank:1};return{label:'Por explorar',css:'gray',rank:0};}
function recommendations(){return [...LESSONS].filter(l=>status(l).rank<3).sort((a,b)=>{const da=latest(a.id,'diag'),db=latest(b.id,'diag');return (da&&da.score<75?0:da?1:2)-(db&&db.score<75?0:db?1:2);}).slice(0,4);}
function badge(l){const s=status(l);return `<span class="badge ${s.css}">${s.label}</span>`;}
function button(label,action,attrs='',css=''){return `<button class="btn ${css}" data-action="${action}" ${attrs}>${label}</button>`;}
function title(head,sub,extra=''){return `<div class="page-title"><div><h1>${head}</h1><p>${sub}</p></div>${extra}</div>`;}
function lessonRow(l,index){return `<a class="lesson-row" href="#tema/${l.id}"><span class="number">${index??areaById(l.area).icon}</span><div><h3>${E(l.title)}</h3><p>${E(areaById(l.area).name)} · ${E(l.codes)}</p></div>${badge(l)}</a>`;}
function areaCard(a){const lessons=LESSONS.filter(l=>l.area===a.id),done=lessons.filter(l=>status(l).rank===3).length;return `<a class="card area-card" href="#area/${a.id}" style="--tint:${a.tint}"><div class="area-top"><span class="area-icon">${a.icon}</span><span class="muted">↗</span></div><h3>${a.name}</h3><p>${a.description}</p><div class="card-meta"><span>${lessons.length} temas</span><span>${done} consolidados</span></div><div class="progress"><span style="width:${done/lessons.length*100}%"></span></div></a>`;}
function stats(){const s=current(),done=LESSONS.filter(l=>status(l).rank===3).length,practice=new Set(s.logs.filter(x=>['match','puzzle'].includes(x.type)).map(x=>x.lesson+'-'+x.type)).size,evidence=s.logs.filter(x=>x.type==='evidence').length,pending=Classroom.isStudent()?Classroom.pendingTasks():s.tasks.filter(t=>!t.done).length;return `<div class="stats"><div class="stat"><small>Temas consolidados</small><strong>${done}<em>/ ${LESSONS.length}</em></strong></div><div class="stat"><small>Juegos practicados</small><strong>${practice}</strong></div><div class="stat"><small>Evidencias observadas</small><strong>${evidence}</strong></div><div class="stat"><small>Tareas pendientes</small><strong>${pending}</strong></div></div>`;}
function renderHome(){const rec=recommendations(),hasDiag=current().logs.some(x=>x.type==='diag'),running=current().quiz;return `${title(`Un paso más, ${E(current().name)}.`, 'Tu camino hacia séptimo empieza con lo que ya sabes.', '<span class="pill">✦ A tu ritmo, con acompañamiento</span>')}<section class="hero"><div><span class="eyebrow">TU PRÓXIMO DESCUBRIMIENTO</span><h2>${hasDiag?'Practica, explica.<br>Y hazlo tuyo.':'Todo gran aprendizaje<br>empieza con una pregunta.'}</h2><p>${hasDiag?'Tu ruta combina juegos, pequeñas pruebas y actividades que puedes compartir con tu docente.':'Descubre tus puntos de partida. El diagnóstico ayuda a decidir qué practicar primero; no es una nota para aprobar.'}</p><a class="btn" href="${running?(running.kind==='diag'?'#diagnostico':'#tema/'+running.lesson):hasDiag&&rec.length?'#tema/'+rec[0].id:'#diagnostico'}">${running?'Continuar prueba en curso':hasDiag?'Continuar mi ruta':'Empezar mi diagnóstico'} <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit small"></div><span class="seed">YS</span><span class="floating float-a">Aa</span><span class="floating float-b">∑</span><span class="floating float-c">★</span></div></section>${stats()}<div class="split"><section><div class="section-head"><h2>Tu siguiente paso</h2><a href="#areas">Ver todos los temas ↗</a></div><div class="lesson-list">${rec.length?rec.map((l,i)=>lessonRow(l,String(i+1).padStart(2,'0'))).join(''):'<div class="empty">Has reunido las evidencias previstas en todos los temas. Tu docente puede revisar y planificar nuevos retos.</div>'}</div></section><section><div class="section-head"><h2>Una clase, varias formas</h2></div><div class="card"><span class="big-icon">✦</span><h3>Aprender también es hacer.</h3><p class="muted">Lee un ejemplo, resuelve un puzzle y explica con tus palabras. Tu docente observa el proceso y registra la evidencia.</p><div class="preview-list">${Teacher.isCloud()?'<a href="#docente"><span class="dot"></span>Guías de clase y rúbricas</a>':''}<a href="${Classroom.isStudent()?'#estudiante':Teacher.isCloud()?'#tareas':'#areas'}"><span class="dot"></span>${Classroom.isStudent()?'Ver mis tareas':Teacher.isCloud()?'Organizar las próximas actividades':'Explorar actividades'}</a><a href="#progreso"><span class="dot"></span>Descubrir avances y necesidades</a></div></div></section></div><div class="section-head"><h2>Un mundo por explorar</h2><span class="muted"><small>8 rutas · ${LESSONS.length} temas</small></span></div><div class="grid">${AREAS.map(areaCard).join('')}</div>`;}
function renderAreas(){return title('Cada área, un descubrimiento.','Elige una ruta o busca el tema que necesitas.')+`<div class="filters"><input id="search" placeholder="Buscar: fracciones, lectura, cuerpo…" aria-label="Buscar temas" value="${E(search)}"><select id="area-filter" aria-label="Filtrar por área"><option value="all">Todas las áreas</option>${AREAS.map(a=>`<option value="${a.id}" ${filterArea===a.id?'selected':''}>${a.name}</option>`).join('')}</select></div><div id="area-results">${areaResults()}</div>`;}
function areaResults(){if(!search&&filterArea==='all')return `<div class="grid">${AREAS.map(areaCard).join('')}</div>`;const list=LESSONS.filter(l=>(filterArea==='all'||l.area===filterArea)&&`${l.title} ${l.explain} ${l.codes}`.toLocaleLowerCase('es').includes(search.toLocaleLowerCase('es')));return `<div class="lesson-list">${list.length?list.map(l=>lessonRow(l)).join(''):'<div class="empty">No encontramos temas con esa búsqueda.</div>'}</div>`;}
function renderArea(a){const list=LESSONS.filter(l=>l.area===a.id);return `<a class="back" href="#areas">← Todas las áreas</a>${title(a.name,a.description)}<div class="notice">Los códigos son referencias de Básica Media. Ajusta la secuencia y dificultad a la planificación de sexto y al punto de partida del estudiante.</div><div class="actions">${button('Diagnosticar esta área','start-diag',`data-area="${a.id}"`)}${Teacher.isAllowed()?'<a class="btn secondary" href="#docente">Planificar una clase</a>':''}</div><div class="section-head"><h2>${list.length} temas para practicar</h2></div><div class="lesson-list">${list.map((l,i)=>lessonRow(l,String(i+1).padStart(2,'0'))).join('')}</div>`;}
function tabs(){return `<div class="tabs" role="tablist" aria-label="Actividad del tema">${[['aprender','01 · Aprender'],['jugar','02 · Juegos'],['prueba','03 · Comprobar'],['explicar','04 · Explicar'],...(Teacher.isAllowed()?[['clase','Guía docente']]:[])].map(([id,label])=>`<button role="tab" aria-selected="${lessonTab===id}" class="${lessonTab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</div>`;}
function renderLesson(l){let html=`<a class="back" href="#area/${l.area}">← ${areaById(l.area).name}</a>${title(E(l.title),E(l.codes),badge(l))}${tabs()}`;const q=current().quiz;if(lessonTab==='prueba'&&q&&q.kind==='knowledge'&&q.lesson===l.id)return html+renderQuiz(q);let body='';
 if(lessonTab==='aprender')body=`<div class="card reading"><span class="eyebrow">ENTENDER ANTES DE MEMORIZAR</span><h2 style="margin-top:14px">La idea que vamos a explorar</h2><p>${E(l.explain)}</p><div class="callout"><h3>Vamos con un ejemplo</h3><p>${E(l.example)}</p></div><h3>Ahora te toca a ti</h3><p>${E(l.activity)}</p>${button('Practicar jugando →','tab','data-tab="jugar"')}</div>`;
 if(lessonTab==='jugar')body=`<div class="game-selector">${button('Relaciona las ideas','game-type','data-type="match"',gameType==='match'?'active':'secondary')}${button('Ordena los pasos','game-type','data-type="puzzle"',gameType==='puzzle'?'active':'secondary')}</div>${renderGame(l)}`;
 if(lessonTab==='prueba'){const k=latest(l.id,'knowledge');body=`<div class="card"><span class="big-icon">◎</span><h2>¿Cómo lo resolverías ahora?</h2><p class="muted">Tres preguntas, sin límite de tiempo. Recibirás una explicación después de cada respuesta. El resultado se registra separado de los juegos y del diagnóstico.</p>${k?`<div class="notice">Último resultado: <strong>${k.score} %</strong> · ${dateLabel(k.date)}. Puedes volver a practicar y repetir.</div>`:''}${button('Iniciar prueba del tema','start-knowledge',`data-lesson="${l.id}"`)}</div>`;}
 if(lessonTab==='explicar')body=`<div class="card"><span class="eyebrow">EVIDENCIA MÁS ALLÁ DEL CUESTIONARIO</span><h2 style="margin-top:12px">Muéstralo con tus palabras.</h2><p>${E(l.activity)}</p><div class="callout"><strong>Exposición breve · 2–3 minutos</strong><p>Explica qué aprendiste, muestra un ejemplo y responde una pregunta. Puedes usar dibujos, objetos o una demostración adaptada.</p></div><ol><li>¿Cuál es la idea más importante?</li><li>¿Cómo la aplicaste? Muestra tu proceso.</li><li>¿Qué cambiarías o cómo resolverías otro ejemplo?</li></ol><p class="muted">Tu docente puede evaluar una exposición, producción artística, juego presencial o práctica corporal. La app no graba audio ni video ni asigna una nota automática a estas evidencias.</p>${Teacher.isAllowed()?button('Registrar evidencia docente','evidence',`data-lesson="${l.id}"`):Classroom.isStudent()?'<a class="btn secondary" href="#estudiante">Volver a mis tareas</a>':''}</div>`;
 if(lessonTab==='clase')body=renderClass(l);
 return html+`<div class="lesson-content">${body}</div>`;
}
function renderClass(l){if(!Teacher.isAllowed())return Teacher.panel();return `<div class="card"><span class="eyebrow">GUÍA DE ACOMPAÑAMIENTO · 35–45 MIN</span><h2 style="margin-top:12px">Una clase alrededor de ${E(l.title.toLowerCase())}</h2><p><strong>Propósito:</strong> comprender el tema, aplicar sus ideas y explicar el proceso con una evidencia.</p>${[['5 min','Activar lo que sabe','Pregunta qué conoce del tema y solicita un ejemplo. Revisa el diagnóstico como una pista, no como conclusión definitiva.'],['10 min','Modelar y conversar',l.explain+' Usa el ejemplo: '+l.example],['10 min','Practicar con apoyo','Resuelve el puzzle y el juego de relaciones. Pide explicar las elecciones; ajusta material, lectura y ritmo si hace falta.'],['10 min','Aplicar y observar',l.activity],['5 min','Cerrar y decidir','Pregunta qué aprendió y qué necesita practicar. Registra la evidencia con rúbrica y asigna una tarea concreta.']].map(([time,t,p])=>`<div class="step"><span>✦</span><div><h3>${t} <small class="muted">· ${time}</small></h3><p>${E(p)}</p></div></div>`).join('')}<div class="callout"><strong>Adaptación</strong><p>Ofrece lectura acompañada, material concreto y respuestas orales. En actividades físicas, acuerda movimientos seguros y accesibles. En temas personales, permite usar ejemplos ficticios.</p></div><div class="actions">${button('Registrar evidencia','evidence',`data-lesson="${l.id}"`)}${button('Asignar clase o tarea','task-new',`data-lesson="${l.id}"`,'secondary')}${button('Imprimir guía','print','','secondary')}</div></div>`;}
function initializeGame(l){if(game&&game.lesson===l.id&&game.type===gameType)return;game={lesson:l.id,type:gameType,selected:null,matched:[],mistakes:0,done:false,feedback:'',order:shuffle(l.sequence.map((_,i)=>i)),left:shuffle(l.questions.map((_,i)=>i)),right:shuffle(l.questions.map((_,i)=>i))};if(game.order.every((x,i)=>x===i))game.order.reverse();}
function renderGame(l){initializeGame(l);if(gameType==='match')return `<div class="card"><span class="eyebrow">JUEGO DE RELACIONES</span><h2 style="margin-top:12px">Cada idea tiene su pareja.</h2><p class="muted">Toca una pregunta y después su respuesta. Sin cronómetro: piensa y explica tu decisión.</p><div class="pairs"><div class="pair-col">${game.left.map(i=>`<button class="pair-btn ${game.matched.includes(i)?'matched':game.selected===i?'selected':''}" data-action="pair-left" data-index="${i}" ${game.matched.includes(i)?'disabled':''}>${E(l.questions[i].prompt)}</button>`).join('')}</div><div class="pair-col">${game.right.map(i=>`<button class="pair-btn ${game.matched.includes(i)?'matched':''}" data-action="pair-right" data-index="${i}" ${game.matched.includes(i)?'disabled':''}>${E(l.questions[i].options[0])}</button>`).join('')}</div></div><div class="feedback" role="status">${E(game.feedback||'Elige primero una pregunta de la izquierda.')}</div><div class="quiz-bottom"><small>${game.matched.length}/3 parejas · ${game.mistakes} intentos incorrectos</small>${game.done?button('Jugar otra vez','game-reset'):''}</div>${game.done?'<p class="muted"><small>Resultado guardado como práctica. Para consolidar, completa la prueba y una evidencia observada.</small></p>':''}</div>`;
return `<div class="card"><span class="eyebrow">PUZZLE DE SECUENCIAS</span><h2 style="margin-top:12px">Pon las ideas en movimiento.</h2><p class="muted">Usa las flechas para ordenar esta secuencia. Explica por qué un paso va antes que otro.</p><div class="sort-list">${game.order.map((idx,pos)=>`<div class="sort-row"><span class="badge gray">${pos+1}</span><span>${E(l.sequence[idx])}</span><button data-action="sort" data-index="${pos}" data-dir="-1" aria-label="Subir paso ${pos+1}" ${pos===0||game.done?'disabled':''}>↑</button><button data-action="sort" data-index="${pos}" data-dir="1" aria-label="Bajar paso ${pos+1}" ${pos===game.order.length-1||game.done?'disabled':''}>↓</button></div>`).join('')}</div>${game.feedback?`<div class="feedback" role="status">${E(game.feedback)}</div>`:''}<div class="actions">${game.done?button('Otro intento','game-reset'):button('Comprobar el orden','sort-check')}</div></div>`;}
function makeQuiz(kind,area,lesson){const list=kind==='knowledge'?[byId(lesson)]:LESSONS.filter(l=>area==='all'||l.area===area);const n=current().logs.filter(x=>x.type==='diag').length;const items=kind==='knowledge'?list[0].questions.map(q=>({lesson:list[0].id,q:q.id})):list.map((l,i)=>({lesson:l.id,q:l.questions[(n+i)%l.questions.length].id}));current().quiz={kind,area,lesson:lesson||null,items:shuffle(items).map(x=>({...x,order:shuffle([0,1,2])})),index:0,answers:[],checked:false,selected:null};save();if(kind==='knowledge'){lessonTab='prueba';render();}else location.hash='diagnostico';render();}
function renderDiagnostic(){const q=current().quiz;if(q&&q.kind==='diag')return title('Conocer el punto de partida.','Responde lo que puedas. Al final revisaremos qué conviene reforzar.')+renderQuiz(q);return `${title('Primero, descubramos lo que sabes.','Un diagnóstico orienta el refuerzo. No decide la promoción escolar.')}<div class="split"><div class="card"><span class="big-icon">◎</span><h2>Una pregunta por tema</h2><p class="muted">Puedes hacer las ${LESSONS.length} preguntas o comenzar por un área. No hay límite de tiempo. ${Classroom.isStudent()?'Tus respuestas en curso permanecen en esta pestaña y los resultados se envían al terminar.':'Tus respuestas se guardan para continuar en este navegador.'} No se muestran soluciones hasta terminar.</p><div class="field"><label for="diag-area">¿Qué quieres explorar?</label><select id="diag-area"><option value="all">Todas las áreas · ${LESSONS.length} preguntas</option>${AREAS.map(a=>`<option value="${a.id}">${a.name} · ${LESSONS.filter(l=>l.area===a.id).length} preguntas</option>`).join('')}</select></div>${button('Empezar diagnóstico','start-diag')}</div><div class="card"><h3>Un punto de partida, varias evidencias</h3><p class="muted">Una sola pregunta no demuestra todo lo que sabes de un tema. Tu docente contrastará el resultado con conversaciones, juegos y producciones.</p><p class="muted">Si necesitas lectura acompañada o responder oralmente, pueden realizarlo juntos. Registra luego las observaciones en el panel docente.</p></div></div>`;}
function renderQuiz(q){const item=q.items[q.index],l=byId(item.lesson),question=l.questions.find(x=>x.id===item.q),correct=q.selected===question.answer;return `<section class="quiz card"><div class="quiz-top"><span>${E(areaById(l.area).name)} · ${E(l.title)}</span><span>${q.index+1} de ${q.items.length}</span></div><div class="progress"><span style="width:${q.index/q.items.length*100}%"></span></div><h2 class="question">${E(question.prompt)}</h2><div class="options">${item.order.map((idx,pos)=>`<button class="option ${q.selected===idx?'selected':''} ${q.checked&&q.kind==='knowledge'?(idx===question.answer?'correct':q.selected===idx?'wrong':''):''}" data-action="quiz-select" data-index="${idx}" ${q.checked?'disabled':''}><span>${String.fromCharCode(65+pos)}</span>${E(question.options[idx])}</button>`).join('')}</div>${q.checked?`<div class="feedback ${q.kind==='knowledge'&&!correct?'error':''}" role="status">${q.kind==='diag'?'Respuesta registrada. Continuaremos sin mostrar la solución.':`<strong>${correct?'Bien razonado.':'Una oportunidad para aprender.'}</strong><br>${E(question.reason)}`}</div>`:''}<div class="quiz-bottom">${button('Salir y continuar luego','quiz-pause','','secondary small')}${q.checked?button(q.index===q.items.length-1?'Ver resultados':'Siguiente →','quiz-next'):button('Guardar respuesta','quiz-check',q.selected===null?'disabled':'')}</div><p class="muted"><small>${Classroom.isStudent()?'El intento en curso permanece en esta pestaña; al terminar se envía el resultado al docente.':'Tu avance se guarda en este navegador.'} Las copias exportadas conservan también el intento en curso.</small></p></section>`;}
function finishQuiz(){const q=current().quiz,report=q.items.map((it,i)=>{const l=byId(it.lesson),question=l.questions.find(x=>x.id===it.q);return{...it,correct:q.answers[i]===question.answer,reason:question.reason};});const score=Math.round(report.filter(x=>x.correct).length/report.length*100);if(q.kind==='diag'){report.forEach(it=>log(it.lesson,'diag',it.correct?100:0,{detail:'Una pregunta de diagnóstico; requiere contraste docente.'}));}else log(q.lesson,'knowledge',score,{detail:`${report.filter(x=>x.correct).length} de ${report.length} respuestas correctas`});current().quiz=null;save();const wrong=report.filter(it=>!it.correct);$('#main').innerHTML=title(q.kind==='diag'?'Ya tenemos un punto de partida.':'Un resultado para seguir aprendiendo.','Revisa las explicaciones y elige tu próximo paso.')+`<div class="card quiz"><div class="result-score">${score} %</div><p>${report.filter(x=>x.correct).length} de ${report.length} respuestas correctas.</p><div class="notice">${q.kind==='diag'?'Este diagnóstico es una muestra breve: no certifica dominio de las destrezas.':'La prueba registra conocimientos. Para consolidar el tema, añade una evidencia observada por el docente.'}</div>${wrong.length?`<h3>Ideas para volver a explorar</h3>${wrong.map(it=>`<div class="callout"><a href="#tema/${it.lesson}">${E(byId(it.lesson).title)}</a><p>${E(it.reason)}</p></div>`).join('')}`:'<p>Acertaste todas las preguntas. El siguiente reto es aplicar y explicar.</p>'}<div class="actions"><a class="btn" href="#inicio">Ver mi ruta</a><a class="btn secondary" href="#progreso">Revisar progreso</a></div></div>`;$('#main').focus();}
function renderTasks(){if(Classroom.isStudent())return Classroom.studentHome();if(!Teacher.isAllowed())return Teacher.panel();const list=[...current().tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999'));return title('Una clase a la vez.','Organiza encuentros, prácticas y tareas del estudiante activo.',button('＋ Nueva actividad','task-new'))+`<div class="card">${list.length?list.map(t=>`<article class="task ${t.done?'done':''}"><input type="checkbox" data-action="task-toggle" data-id="${t.id}" aria-label="Completar ${E(t.title)}" ${t.done?'checked':''}><div class="task-body"><h3>${E(t.title)}</h3><p>${E(t.format)} · ${dateLabel(t.date)} ${t.date&&t.date<day()&&!t.done?'· Pendiente de fecha anterior':''}</p>${t.lesson?`<a class="skill-code" href="#tema/${t.lesson}">${E(byId(t.lesson)?.title||'Tema')}</a>`:''}<p style="white-space:pre-wrap">${E(t.notes)}</p></div><div class="task-tools">${button('Editar','task-edit',`data-id="${t.id}"`,'secondary small')}${button('Eliminar','task-delete',`data-id="${t.id}"`,'danger small')}</div></article>`).join(''):'<div class="empty">Aquí aparecerán tus próximas clases y tareas.<br>Asigna una actividad con un propósito y una forma de mostrar lo aprendido.</div>'}</div>`;}
function renderTeacher(){if(Classroom.isStudent())return title('Espacio docente','Cierra primero tu sesión de estudiante.')+'<a class="btn" href="#estudiante">Volver a mis tareas</a>';if(!Teacher.isAllowed())return Teacher.panel();return Teacher.toolbar()+title('Acompañar también es observar.','Guías de clase y evaluación de actuaciones reales.')+`<div class="notice"><strong>Estudiante: ${E(current().name)}</strong> · <a href="#ajustes">Administrar o borrar datos de prueba</a>. Selecciona primero al estudiante. Estás en el espacio privado de profesores. Los registros docentes se guardan en la nube.</div>${Classroom.teacherPanel()}${stats()}<div class="card"><div class="form-grid"><div class="field"><label for="teacher-topic">Tema para la clase</label><select id="teacher-topic">${LESSONS.map(l=>`<option value="${l.id}">${areaById(l.area).name} · ${E(l.title)}</option>`).join('')}</select></div><div><p class="muted"><small>La rúbrica admite exposición, juego observado, proyecto, producción artística y práctica corporal.</small></p><div class="actions">${button('Abrir guía','teacher-guide')}${button('Evaluar evidencia','teacher-evidence','','secondary')}</div></div></div></div><div class="section-head"><h2>Últimas evidencias</h2></div>${evidenceTable()}<div class="section-head"><h2>Cómo interpretamos el avance</h2></div><div class="grid"><div class="card"><h3>1 · Diagnosticar</h3><p class="muted">Una muestra inicial orienta la ruta. Contrasta aciertos y dificultades con otras actividades.</p></div><div class="card"><h3>2 · Practicar y comprender</h3><p class="muted">Los juegos cuentan como práctica. La prueba guarda el último resultado conceptual del tema.</p></div><div class="card"><h3>3 · Aplicar y explicar</h3><p class="muted">Un tema aparece consolidado con prueba ≥ 75 % y última evidencia con nivel ≥ 3 en los cuatro criterios. Es una regla pedagógica orientativa, ajustable mediante revisión docente; no equivale a promoción oficial.</p></div></div>`;}
function evidenceTable(){const list=current().logs.filter(l=>l.type==='evidence').slice(-12).reverse();return list.length?`<div class="card table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Tema y modalidad</th><th>Niveles</th><th>Observaciones</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${dateLabel(x.date)}</td><td><a href="#tema/${x.lesson}">${E(byId(x.lesson).title)}</a><br>${E(x.mode)}</td><td>${x.levels.join(' · ')}<br><small>${x.score} % rúbrica</small></td><td style="white-space:pre-wrap">${E(x.detail)}</td><td>${button('Eliminar','evidence-delete',`data-id="${x.id}"`,'danger small')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay evidencias observadas todavía. Registra una actuación real después de la clase.</div>';}
function renderProgress(){const s=current();return title('El aprendizaje deja huellas.',`Informe de ${E(s.name)} · ${dateLabel(now())}`,button('Imprimir informe','print','','secondary'))+stats()+`<div class="notice">${Teacher.isAllowed()?'Valoración del espacio docente.':Classroom.isStudent()?'Resultados compartidos y valoraciones de tu docente.':'Práctica local: los registros importados no acreditan una valoración docente verificada.'} El docente puede marcar o reabrir el dominio con una justificación. Regla automática: consolidado = última prueba del tema ≥ 75 % y última rúbrica con los cuatro criterios ≥ 3. Un diagnóstico o juego por sí solo no acredita dominio. Los porcentajes de cada instrumento se muestran por separado.</div><div class="card table-wrap"><table class="table"><thead><tr><th>Tema</th><th>Diagnóstico</th><th>Prueba</th><th>Juegos</th><th>Evidencia</th><th>Estado</th></tr></thead><tbody>${LESSONS.map(l=>{const d=latest(l.id,'diag'),k=latest(l.id,'knowledge'),m=latest(l.id,'match'),p=latest(l.id,'puzzle'),e=latest(l.id,'evidence');return `<tr><td><a href="#tema/${l.id}">${E(l.title)}</a><br><small>${areaById(l.area).name}</small></td><td>${d?d.score+' %':'—'}</td><td>${k?k.score+' %':'—'}</td><td>${m?'Parejas '+m.score+' %':'—'}${p?'<br>Secuencia '+p.score+' %':''}</td><td>${e?e.levels.join(' · '):'—'}</td><td>${badge(l)}</td></tr>`;}).join('')}</tbody></table></div><div class="section-head"><h2>Historial reciente</h2></div><div class="card">${s.logs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Actividad</th><th>Instrumento</th><th>Resultado</th></tr></thead><tbody>${s.logs.slice(-30).reverse().map(x=>`<tr><td>${dateLabel(x.date)}</td><td>${E(byId(x.lesson).title)}</td><td>${({diag:'Diagnóstico',knowledge:'Prueba del tema',match:'Juego de parejas',puzzle:'Puzzle',evidence:'Evidencia docente'})[x.type]}</td><td>${x.score} %</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">El historial aparecerá cuando completes una actividad.</p>'}</div>`;}
function renderSettings(){return title(Teacher.isCloud()?'Administrar estudiantes':'Datos de práctica','Selecciona el perfil arriba para gestionar sus datos.')+`<div class="split"><div class="card"><h2>Tus datos, a mano</h2><p class="muted">${Teacher.isCloud()?'Estás en el espacio docente: sus registros se guardan en la nube al confirmar la conexión. Los estudiantes con cuenta asociada comparten resultados al completar actividades. Actualiza «Trabajo en casa» para revisarlos.':'Sin cuenta, la práctica se guarda en este navegador. Con una cuenta estudiantil asociada, las entregas y los resultados completados se envían al docente. Los intentos sin terminar permanecen en la pestaña.'} Borrar los datos del navegador puede eliminar el progreso. Exporta copias periódicamente; importar añade perfiles como copias nuevas.</p><div class="actions">${button('Exportar copia JSON','export')}${Classroom.isStudent()?'':button('Importar copia','import','','secondary')}<input type="file" id="import-file" accept="application/json,.json" hidden></div><p><small class="muted">La copia incluye los perfiles y los intentos de prueba en curso de esta sesión. Las entregas, devoluciones y valoraciones manuales se exportan desde «Trabajo en casa»; descarga los adjuntos por separado. Guárdala en un lugar privado.</small></p><hr style="border:0;border-top:1px solid var(--line)"><h3>Estudiante activo: ${E(current().name)}</h3><div class="actions">${Classroom.isStudent()?'<span>Perfil administrado por tu docente.</span>':button('Cambiar nombre','rename','','secondary small')+button('Borrar datos de prueba','student-reset','','secondary small')+button('Eliminar estudiante','student-delete','','danger small')}</div><p class="muted"><small>Usa alias si lo prefieres. El repositorio público contiene solo código y contenido educativo; los registros locales no se publican allí.</small></p></div><div class="card"><h2>Alcance de esta versión</h2><p class="muted">${LESSONS.length} módulos iniciales y ${LESSONS.reduce((n,l)=>n+l.questions.length,0)} preguntas propias. Es una base de nivelación, no una cobertura exhaustiva de todas las DCD ni una prueba estandarizada. Ajusta contenidos y exigencia a la planificación institucional de sexto.</p><p class="muted">Las rúbricas requieren valoración humana. La app no graba ni analiza voz, movimiento o video; el estudiante puede adjuntar archivos ya creados para que el docente los revise. Puedes instalarla desde las opciones de tu navegador compatibles; el uso sin conexión estará disponible tras una primera carga completa.</p></div></div><div class="section-head"><h2>Fuentes y relación curricular</h2></div><div class="card"><p>Las destrezas de Básica Media abarcan quinto, sexto y séptimo. Los códigos de cada módulo son referencias para orientar la planificación y deben revisarse con la desagregación institucional. Los textos explicativos, preguntas y actividades de esta app son contenido propio.</p><ul class="source-list"><li><a href="https://educacion.gob.ec/curriculo-priorizado/" target="_blank" rel="noopener noreferrer">Ministerio de Educación · Currículo vigente</a></li><li><a href="https://educacion.gob.ec/wp-content/uploads/downloads/2025/08/Curriculo-Priorizado-EGB-Media.pdf" target="_blank" rel="noopener noreferrer">Currículo Priorizado de Básica Media · 2025</a></li><li><a href="https://recursos.educacion.gob.ec/red/textossexto/" target="_blank" rel="noopener noreferrer">Textos oficiales de sexto de EGB</a></li><li><a href="https://educacion.gob.ec/curriculo-media/" target="_blank" rel="noopener noreferrer">Orientaciones de Básica Media</a></li></ul><p class="muted"><small>Los umbrales de progreso de Yunga School son orientativos. No reemplazan indicadores oficiales, adaptaciones individuales ni decisiones de promoción de la institución.</small></p></div>`;}
function renderAccess(){return `<section class="access-welcome"><span class="pill">YUNGA SCHOOL · 6.º EGB</span><h1>Tu aula, en un solo lugar.</h1><p>Elige tu acceso para empezar.</p><div class="access-grid"><a class="access-card" href="#estudiante"><span class="access-symbol">▣</span><h2>Soy estudiante</h2><p>Mis tareas, juegos, pruebas y avances.</p><span class="btn">Entrar como estudiante →</span></a><a class="access-card teacher-access" href="#docente"><span class="access-symbol">◇</span><h2>Soy docente</h2><p>Estudiantes, clases, entregas y evaluación.</p><span class="btn">Entrar como docente →</span></a></div><a class="practice-link" href="#practica">Practicar sin cuenta en este dispositivo</a></section>`;}
function navigation(page){
 const teacher=Teacher.isCloud(),student=Classroom.isStudent(),portal=!teacher&&!student&&!practiceMode;
 document.body.classList.toggle('access-mode',portal);
 document.body.dataset.role=teacher?'teacher':student?'student':portal?'access':'practice';
 const links=teacher?[['docente','◇','Panel docente'],['tareas','☑','Clases y tareas'],['progreso','↗','Progreso del estudiante'],['areas','▦','Contenidos y guías'],['ajustes','⚙','Administrar estudiantes']]:student?[['estudiante','☑','Mis tareas'],['inicio','⌂','Mi ruta'],['areas','▦','Temas y juegos'],['diagnostico','◎','Diagnóstico'],['progreso','↗','Mi progreso']]:portal?[]:[['inicio','⌂','Mi ruta'],['areas','▦','Temas y juegos'],['diagnostico','◎','Diagnóstico'],['progreso','↗','Mi progreso'],['ajustes','⚙','Datos de práctica'],['acceso','◇','Volver a los accesos']];
 $('#nav').innerHTML=links.map(([route,icon,label])=>`<a href="#${route}" data-page="${route}" class="${route===page||(page==='tema'||page==='area')&&route==='areas'?'active':''}"><span>${icon}</span>${label}</a>`).join('');
 $('#student').disabled=student||teacher&&!Teacher.isAllowed();$('#add-student').disabled=student||teacher&&!Teacher.isAllowed();
 $('.student-select').hidden=portal||student;$('.source-link').hidden=portal||student;
 $('.source-link').href=teacher?'#ajustes':'#acceso';$('.source-link').textContent=teacher?'Administrar estudiantes':'Cambiar acceso';
 $('.brand').href=teacher?'#docente':student?'#estudiante':practiceMode?'#inicio':'#acceso';
 $('#student').innerHTML=state.students.map(s=>`<option value="${s.id}" ${s.id===state.active?'selected':''}>${E(s.name)}</option>`).join('');$('#profile-label').textContent=portal?'':current().name;
 $('#add-student').textContent=teacher?'+ Añadir estudiante':'+ Nuevo perfil de práctica';
 const exit=teacher?button('Cerrar sesión','auth-logout','','secondary small'):student?button('Cerrar sesión','class-logout','','secondary small'):'';
 $('#session-tools').innerHTML=exit;
 $('footer').innerHTML=portal?'Yunga School · Aprender paso a paso':`Yunga School · ${teacher?'Área docente':student?'Área estudiantil':'Práctica en este dispositivo'} <a href="${teacher?'#ajustes':student?'#estudiante':'#acceso'}">${teacher?'Administrar datos':student?'Mis tareas':'Cambiar acceso'}</a>`;
}
function render(){let [route,id]=location.hash.slice(1).split('/'),page=route||'acceso';
 if(!Teacher.isCloud()&&!Classroom.isStudent()){
  if(['acceso','estudiante','docente'].includes(page))practiceMode=false;
  else if(page==='practica'||['areas','area','tema','diagnostico','progreso','ajustes'].includes(page))practiceMode=true;
  if(page==='inicio'&&!practiceMode)page='acceso';
 }
 if(page==='practica')page='inicio';
 if(page==='acceso'&&(Teacher.isCloud()||Classroom.isStudent()))page=Teacher.isCloud()?'docente':'estudiante';
 navigation(page);let html;
 if(Teacher.isCloud()&&!Teacher.isAllowed())html=Teacher.panel();
 else switch(page){case'acceso':html=renderAccess();break;case'estudiante':html=Classroom.studentHome();break;case'areas':html=renderAreas();break;case'area':html=areaById(id)?renderArea(areaById(id)):renderHome();break;case'tema':html=byId(id)?renderLesson(byId(id)):renderHome();break;case'diagnostico':html=renderDiagnostic();break;case'tareas':html=renderTasks();break;case'docente':html=renderTeacher();break;case'progreso':html=renderProgress();break;case'ajustes':html=renderSettings();break;default:html=Teacher.isCloud()?renderTeacher():renderHome();}
 Teacher.stamp();Classroom.stamp();if(document.body.dataset.role==='access')$('#access-label').textContent='Elige tu acceso';
 $('#main').innerHTML=(storageFailed&&!Teacher.isCloud()&&!Classroom.isStudent()?'<div class="notice" role="alert">El guardado local no está disponible. Exporta una copia antes de cerrar.</div>':'')+html;
}

function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
const criteria=['Comprende la idea y usa conceptos adecuados','Aplica el procedimiento o realiza la actividad','Explica decisiones con ejemplos o evidencias','Responde, revisa y actúa con cuidado / colaboración'];
function evidenceModal(id){if(!Teacher.requireTeacher())return;const l=byId(id);openModal(`<h2>Una evidencia observada</h2><p class="muted">${E(current().name)} · ${E(l.title)}</p><form id="evidence-form" data-lesson="${id}"><div class="field"><label for="e-mode">Modalidad</label><select id="e-mode"><option>Exposición breve</option><option>Juego presencial observado</option><option>Proyecto o resolución práctica</option><option>Producción artística</option><option>Práctica corporal adaptada</option></select></div><p><small>1 · Inicio &nbsp; 2 · Con apoyo &nbsp; 3 · Autónomo &nbsp; 4 · Explica y transfiere. Valora cada criterio según lo observado; adapta la evidencia al estudiante.</small></p><table class="rubric"><tbody>${criteria.map((c,i)=>`<tr><td><label for="criterion-${i}">${c}</label></td><td><select id="criterion-${i}" name="criterion-${i}" required><option value="">Sin valorar</option>${[1,2,3,4].map(n=>`<option value="${n}">${n} · ${['','Inicio','Con apoyo','Autónomo','Transfiere'][n]}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table><div class="field"><label for="e-note">Observaciones y siguiente paso</label><textarea id="e-note" maxlength="5000" placeholder="¿Qué hizo? ¿Qué apoyo recibió? ¿Qué conviene practicar?"></textarea></div><button class="btn" type="submit">Guardar evidencia</button></form>`);}
function taskModal(existing=null,lesson=''){if(!Teacher.requireTeacher())return;const t=existing||{title:'',lesson,format:'Clase de refuerzo',date:day(),notes:''};openModal(`<h2>${existing?'Editar':'Nueva'} actividad</h2><p class="muted">Para ${E(current().name)}</p><form id="task-form" data-id="${existing?.id||''}"><div class="field"><label for="t-title">Título</label><input id="t-title" maxlength="120" required value="${E(t.title)}" placeholder="Ej.: explicar fracciones con un dibujo"></div><div class="field"><label for="t-topic">Tema</label><select id="t-topic"><option value="">Actividad general</option>${LESSONS.map(l=>`<option value="${l.id}" ${l.id===t.lesson?'selected':''}>${E(l.title)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="t-date">Fecha</label><input type="date" id="t-date" value="${E(t.date)}"></div><div class="field"><label for="t-format">Formato</label><select id="t-format">${['Clase de refuerzo','Tarea práctica','Juego observado','Exposición','Proyecto','Evaluación'].map(f=>`<option ${f===t.format?'selected':''}>${f}</option>`).join('')}</select></div></div><div class="field"><label for="t-notes">Indicaciones y evidencia esperada</label><textarea id="t-notes" maxlength="3000">${E(t.notes)}</textarea></div><button type="submit" class="btn">Guardar actividad</button></form>`);}
function nameModal(rename=false){if(Classroom.isStudent())return;if(Teacher.isCloud()&&!Teacher.isAllowed())return;openModal(`<h2>${rename?'Cambiar nombre':'Un nuevo camino'}</h2><form id="name-form" data-rename="${rename}"><div class="field"><label for="s-name">Nombre o alias del estudiante</label><input id="s-name" maxlength="60" required value="${rename?E(current().name):''}" placeholder="Puedes usar un alias"></div><button type="submit" class="btn">Guardar estudiante</button></form>`);}
function confirmModal(message,action,id=''){openModal(`<h2>Confirmar eliminación</h2><p>${E(message)}</p><p class="muted">Exporta una copia si necesitas conservar estos datos.</p><div class="actions">${button('Eliminar','confirm-'+action,`data-id="${E(id)}"`,'danger')}${button('Cancelar','close-modal','','secondary')}</div>`);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;if(Classroom.isBusy()&&action==='close-modal')return;if(Classroom.isStudent()&&['import','rename','student-reset','student-delete','confirm-student','confirm-task','task-edit','task-new','task-delete','task-toggle','evidence','confirm-evidence'].includes(action))return;if(Teacher.isCloud()&&!Teacher.isAllowed()&&!['export','close-modal','auth-logout','auth-discard'].includes(action))return;if(['evidence','teacher-guide','teacher-evidence','evidence-delete','confirm-evidence','task-new','task-edit','task-toggle','task-delete','confirm-task'].includes(action)&&!Teacher.requireTeacher())return;const id=location.hash.slice(1).split('/')[1],l=byId(id),q=current().quiz;switch(action){
case'tab':lessonTab=b.dataset.tab;render();break;
case'game-type':gameType=b.dataset.type;render();break;
case'game-reset':game=null;render();break;
case'pair-left':game.selected=Number(b.dataset.index);game.feedback='Ahora elige la respuesta de la derecha.';render();break;
case'pair-right':if(game.selected===null){toast('Elige primero una pregunta.');break;}if(game.selected===Number(b.dataset.index)){game.matched.push(game.selected);game.feedback=l.questions[game.selected].reason;game.selected=null;if(game.matched.length===3){game.done=true;const score=Math.round(3/(3+game.mistakes)*100);log(l.id,'match',score,{detail:`3 parejas; ${game.mistakes} intentos incorrectos`});game.feedback+=' ¡Completaste las parejas!';}}else{game.mistakes++;game.feedback='Esa respuesta no corresponde. Revisa la pregunta e inténtalo otra vez.';}render();break;
case'sort':{const from=Number(b.dataset.index),to=from+Number(b.dataset.dir);if(to>=0&&to<game.order.length)[game.order[from],game.order[to]]=[game.order[to],game.order[from]];render();break;}
case'sort-check':if(game.order.every((x,i)=>x===i)){game.done=true;const score=Math.round(100/(1+game.mistakes*.25));log(l.id,'puzzle',score,{detail:`Secuencia resuelta; ${game.mistakes} comprobaciones previas`});game.feedback='¡Secuencia completa! Explica por qué organizaste los pasos así. Práctica guardada.';}else{game.mistakes++;game.feedback='Todavía hay pasos fuera de lugar. Piensa qué necesita ocurrir antes y vuelve a probar.';}render();break;
case'start-diag':if(q){openModal(`<h2>Hay una prueba en curso</h2><p>Continúala o descártala antes de iniciar otra.</p><div class="actions">${button('Continuar','quiz-resume')}${button('Descartar intento','quiz-discard','','danger')}</div>`);}else makeQuiz('diag',b.dataset.area||$('#diag-area')?.value||'all');break;
case'start-knowledge':if(q){openModal(`<h2>Hay una prueba en curso</h2><p>Continúala o descártala antes de iniciar otra.</p><div class="actions">${button('Continuar','quiz-resume')}${button('Descartar intento','quiz-discard','','danger')}</div>`);}else makeQuiz('knowledge',null,b.dataset.lesson);break;
case'quiz-select':q.selected=Number(b.dataset.index);save();render();break;
case'quiz-check':if(q.selected===null)break;q.answers[q.index]=q.selected;q.checked=true;save();render();break;
case'quiz-next':if(q.index===q.items.length-1)finishQuiz();else{q.index++;q.selected=null;q.checked=false;save();render();}break;
case'quiz-pause':location.hash='inicio';toast(Classroom.isStudent()?'Intento conservado en esta pestaña. Al completarlo se enviarán los resultados.':'Intento guardado. Puedes continuar desde Diagnóstico o el tema.');break;
case'quiz-resume':closeModal();if(q.kind==='knowledge'){lessonTab='prueba';location.hash='tema/'+q.lesson;}else location.hash='diagnostico';render();break;
case'quiz-discard':current().quiz=null;save();closeModal();render();toast('Intento descartado; las actividades completadas se conservan.');break;
case'evidence':evidenceModal(b.dataset.lesson);break;
case'teacher-guide':lessonTab='clase';location.hash='tema/'+$('#teacher-topic').value+'/clase';render();break;
case'teacher-evidence':evidenceModal($('#teacher-topic').value);break;
case'evidence-delete':confirmModal('Se eliminará esta evidencia y se recalculará el estado del tema.','evidence',b.dataset.id);break;
case'confirm-evidence':current().logs=current().logs.filter(x=>x.id!==b.dataset.id);save();closeModal();render();break;
case'task-new':taskModal(null,b.dataset.lesson||'');break;
case'task-edit':taskModal(current().tasks.find(t=>t.id===b.dataset.id));break;
case'task-toggle':{const t=current().tasks.find(t=>t.id===b.dataset.id);t.done=b.checked;save();render();break;}
case'task-delete':confirmModal('Se eliminará esta actividad de la planificación.','task',b.dataset.id);break;
case'confirm-task':current().tasks=current().tasks.filter(t=>t.id!==b.dataset.id);save();closeModal();render();break;
case'print':window.print();break;
case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='yunga-school-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia exportada con todos los estudiantes.');break;}
case'import':$('#import-file').click();break;
case'rename':nameModal(true);break;
case'student-delete':Classroom.cleanupModal('delete');break;
case'student-reset':Classroom.cleanupModal('reset');break;

case'close-modal':closeModal();break;
}});
document.addEventListener('submit',event=>{const f=event.target;if(!['name-form','task-form','evidence-form'].includes(f.id))return;event.preventDefault();if(Classroom.isStudent())return;if(Teacher.isCloud()&&!Teacher.isAllowed())return;if(['task-form','evidence-form'].includes(f.id)&&!Teacher.requireTeacher())return;if(!f.reportValidity())return;if(f.id==='name-form'){const name=$('#s-name').value.trim();if(!name){toast('Escribe un nombre o alias.');return;}if(f.dataset.rename==='true')current().name=name;else{if(state.students.length>=20){toast('Máximo 20 perfiles en esta versión.');return;}const s=newStudent(name);state.students.push(s);state.active=s.id;game=null;}}if(f.id==='task-form'){const title=$('#t-title').value.trim();if(!title){toast('Escribe un título.');return;}const old=current().tasks.find(t=>t.id===f.dataset.id),t={id:old?.id||uid(),title,lesson:$('#t-topic').value,format:$('#t-format').value,date:$('#t-date').value,notes:$('#t-notes').value.trim(),done:old?.done||false};if(old)Object.assign(old,t);else{if(current().tasks.length>=500){toast('Exporta y organiza tus tareas: máximo 500 por perfil.');return;}current().tasks.push(t);}}if(f.id==='evidence-form'){const levels=criteria.map((_,i)=>Number($('#criterion-'+i).value));if(levels.some(v=>v<1||v>4))return;log(f.dataset.lesson,'evidence',Math.round(levels.reduce((a,b)=>a+b,0)/16*100),{levels,mode:$('#e-mode').value,detail:$('#e-note').value.trim()});}save();closeModal();render();toast(Teacher.isCloud()?'Registrado para '+current().name+'. Comprueba el estado de guardado en la barra superior.':'Guardado para '+current().name+'.');});
$('#add-student').addEventListener('click',()=>nameModal());
$('#student').addEventListener('change',event=>{if(Classroom.isStudent())return;if(Teacher.isCloud()&&!Teacher.isAllowed())return;state.active=event.target.value;lessonTab='aprender';game=null;save();render();});
$('.modal-close').addEventListener('click',()=>{if(!Classroom.isBusy())closeModal();});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;$('#area-results').innerHTML=areaResults();}});
document.addEventListener('change',async event=>{if(event.target.id==='area-filter'){filterArea=event.target.value;$('#area-results').innerHTML=areaResults();}if(event.target.id==='import-file'){if(Classroom.isStudent())return;const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('La copia supera 5 MB.');const incoming=sanitize(JSON.parse(await file.text()));if(state.students.length+incoming.students.length>20)throw Error('La importación superaría 20 perfiles.');incoming.students.forEach(s=>{s.id=uid();s.name=s.name+' (copia)';s.logs.forEach(x=>x.id=uid());s.tasks.forEach(x=>x.id=uid());state.students.push(s);});state.active=incoming.students[0].id;save();game=null;render();toast('Copia importada como perfiles nuevos. No se sobrescribieron los existentes.');}catch(error){toast('No se importó la copia: '+error.message);}event.target.value='';}});
window.addEventListener('hashchange',()=>{lessonTab=location.hash.slice(1).split('/')[2]||'aprender';game=null;const id=location.hash.slice(1).split('/')[1];if(current().quiz?.kind==='knowledge'&&current().quiz.lesson===id)lessonTab='prueba';render();window.scrollTo(0,0);$('#main').focus();});
function sanitize(raw){
 if(!raw||raw.version!==1||!Array.isArray(raw.students)||raw.students.length<1||raw.students.length>20)throw Error('Formato o versión no compatible.');
 const text=(x,max)=>typeof x==='string'?x.slice(0,max):'';
 const validDate=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));
 const students=raw.students.map(s=>{if(!s||typeof s.name!=='string'||!s.name.trim()||typeof s.id!=='string'||!/^[a-zA-Z0-9-]{1,100}$/.test(s.id))throw Error('Perfil no válido.');
 const logs=(Array.isArray(s.logs)?s.logs:[]).slice(-1000).map(x=>{if(!x||!byId(x.lesson)||!['diag','knowledge','match','puzzle','evidence'].includes(x.type)||typeof x.score!=='number'||!Number.isFinite(x.score)||x.score<0||x.score>100||!validDate(x.date))throw Error('Resultado no válido.');const out={id:typeof x.id==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x.id)?x.id:uid(),lesson:x.lesson,type:x.type,score:x.score,date:x.date,detail:text(x.detail,5000)};if(x.type==='evidence'){if(!Array.isArray(x.levels)||x.levels.length!==4||x.levels.some(n=>!Number.isInteger(n)||n<1||n>4))throw Error('Rúbrica no válida.');out.levels=[...x.levels];out.mode=text(x.mode,100);out.score=Math.round(out.levels.reduce((a,b)=>a+b,0)/16*100);}return out;});
 const tasks=(Array.isArray(s.tasks)?s.tasks:[]).slice(0,500).map(t=>{if(!t||typeof t.title!=='string'||!t.title.trim()||t.lesson&&!byId(t.lesson)||t.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||!validDate(t.date)))throw Error('Tarea no válida.');return{id:typeof t.id==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(t.id)?t.id:uid(),title:text(t.title,120),lesson:t.lesson||'',date:t.date||'',format:text(t.format,100),notes:text(t.notes,3000),done:t.done===true};});
 let quiz=null;if(s.quiz){const q=s.quiz;if(!['diag','knowledge'].includes(q.kind)||!Array.isArray(q.items)||q.items.length<1||q.items.length>LESSONS.length||!Number.isInteger(q.index)||q.index<0||q.index>=q.items.length||q.selected!==null&&![0,1,2].includes(q.selected)||!Array.isArray(q.answers)||q.answers.some(n=>![0,1,2].includes(n))||q.answers.length!==(q.checked===true?q.index+1:q.index))throw Error('Intento no válido.');if(q.kind==='knowledge'&&!byId(q.lesson))throw Error('Tema de intento no válido.');const items=q.items.map(it=>{const l=byId(it.lesson);if(!l||!l.questions.some(a=>a.id===it.q)||!Array.isArray(it.order)||it.order.length!==3||new Set(it.order).size!==3||it.order.some(n=>![0,1,2].includes(n)))throw Error('Pregunta no válida.');return{lesson:it.lesson,q:it.q,order:[...it.order]};});quiz={kind:q.kind,lesson:q.lesson||null,area:q.area||'all',items,index:q.index,answers:[...q.answers],selected:q.selected,checked:q.checked===true};}
 return{id:s.id,name:text(s.name.trim(),60),logs,tasks,quiz};});
 if(new Set(students.map(s=>s.id)).size!==students.length)throw Error('Perfiles duplicados.');return{version:1,active:students.some(s=>s.id===raw.active)?raw.active:students[0].id,students};
}
render();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>toast('El modo sin conexión no pudo activarse; la app sigue disponible con conexión.'));

